-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. FACILITIES (Cơ sở / Kho)
CREATE TABLE IF NOT EXISTS vgvina_facilities (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name TEXT NOT NULL,
    address TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. USERS (Người dùng) - Existing table
-- Table already exists with BIGINT ID according to user feedback
