create table public.vgvina_users (
  id bigint generated by default as identity not null,
  username text not null,
  password_hash text not null,
  full_name text null,
  email text null,
  phone_number text null,
  role text null default 'Guest'::text,
  status text null default 'Pending'::text,
  created_at timestamp with time zone null default now(),
  updated_at timestamp with time zone null default now(),
  last_login_at timestamp with time zone null,
  role_id uuid null,
  constraint vgvina_users_pkey primary key (id),
  constraint vgvina_users_username_key unique (username),
  constraint vgvina_users_role_id_fkey foreign KEY (role_id) references vgvina_roles (id) on delete set null
) TABLESPACE pg_default;

create index IF not exists idx_users_username on public.vgvina_users using btree (username) TABLESPACE pg_default;

create index IF not exists idx_users_role on public.vgvina_users using btree (role_id) TABLESPACE pg_default;

create trigger audit_users_changes
after INSERT
or DELETE
or
update on vgvina_users for EACH row
execute FUNCTION audit_log_changes ();